/**
 * Fixed, reviewed replies for messages routed CRISIS or THIRD_PARTY.
 *
 * These are deliberately not generated by an LLM: a person who may be in danger
 * should always get the same checked wording and the right helpline, whether or
 * not the model is up, and however the model would have phrased it.
 *
 * Region comes from CRISIS_REGION (IN, US, UK) and defaults to INTL, which lists
 * India and the US plus a worldwide directory.
 */

const HELPLINES = {
  IN: {
    primary: { name: 'Tele-MANAS, the national mental health helpline', contact: 'call 14416 or 1-800-891-4416 (free, 24/7)' },
    emergency: '112',
  },
  US: {
    primary: { name: 'the 988 Suicide & Crisis Lifeline', contact: 'call or text 988 (free, 24/7)' },
    extra: { name: 'Crisis Text Line', contact: 'text HOME to 741741' },
    emergency: '911',
  },
  UK: {
    primary: { name: 'Samaritans', contact: 'call 116 123 (free, 24/7)' },
    emergency: '999',
  },
};
const DIRECTORY = { name: 'Find A Helpline', contact: 'findahelpline.com lists free services in your country' };

function regionFrom(env = process.env) {
  const r = String(env.CRISIS_REGION || 'INTL').toUpperCase();
  return HELPLINES[r] ? r : 'INTL';
}

function helplineLines(region) {
  if (region === 'INTL') {
    return [
      `In India: ${HELPLINES.IN.primary.name}, ${HELPLINES.IN.primary.contact}. Emergency: ${HELPLINES.IN.emergency}.`,
      `In the US: ${HELPLINES.US.primary.name}, ${HELPLINES.US.primary.contact}. Emergency: ${HELPLINES.US.emergency}.`,
      `Anywhere else: ${DIRECTORY.contact}.`,
    ];
  }
  const h = HELPLINES[region];
  const lines = [`${h.primary.name}: ${h.primary.contact}.`];
  if (h.extra) lines.push(`${h.extra.name}: ${h.extra.contact}.`);
  lines.push(`In an emergency, call ${h.emergency}.`);
  return lines;
}

function emergencyNumber(region) {
  return region === 'INTL' ? 'your local emergency number (112 in India, 911 in the US)' : HELPLINES[region].emergency;
}

function crisisReply(region, imminent) {
  const parts = [
    "I'm really glad you told me, and I'm taking what you said seriously. You don't have to go through this alone.",
  ];
  if (imminent) {
    parts.push(`If you might act on these thoughts soon, please call ${emergencyNumber(region)} now, or go to the nearest emergency department.`);
  }
  parts.push('Please reach out to someone who can talk with you right now:');
  parts.push(...helplineLines(region).map(l => `• ${l}`));
  parts.push(
    "If you can, let someone you trust know how you're feeling, and stay near them. Are you safe right now?"
  );
  return parts.join('\n');
}

function thirdPartyReply(region) {
  return [
    "It's good that you're looking out for them. What they said should be taken seriously.",
    "It's okay to ask them directly whether they're thinking about suicide; asking does not put the idea in their head. Listen without judging, and help them reach support:",
    ...helplineLines(region).map(l => `• ${l}`),
    `If they're in immediate danger, call ${emergencyNumber(region)} and don't leave them alone.`,
    'Supporting someone is hard. Please look after yourself too, and talk to someone you trust about it.',
  ].join('\n');
}

function concernFooter(region) {
  const line = region === 'INTL'
    ? `${HELPLINES.IN.primary.name} (India, 14416) and 988 (US) are free and open 24/7, or see ${DIRECTORY.contact}.`
    : `${HELPLINES[region].primary.name}: ${HELPLINES[region].primary.contact}.`;
  return `\n\nIf things get harder or you have thoughts of hurting yourself, you can talk to someone any time. ${line}`;
}

/**
 * The reply to send instead of an LLM response, or null when the LLM may answer.
 * analysis is what ChatService.detectCrisis returns (route, imminent).
 */
function safetyReply(analysis, region = regionFrom()) {
  if (analysis.route === 'CRISIS') {
    return { content: crisisReply(region, analysis.imminent), source: 'safety', confidence: 1 };
  }
  if (analysis.route === 'THIRD_PARTY') {
    return { content: thirdPartyReply(region), source: 'safety', confidence: 1 };
  }
  return null;
}

/** Helplines in the { name, number, description } shape the API already returns. */
function resources(region = regionFrom()) {
  const list = region === 'INTL' ? ['IN', 'US'] : [region];
  return {
    crisis_lines: [
      ...list.flatMap(r => [HELPLINES[r].primary, ...(HELPLINES[r].extra ? [HELPLINES[r].extra] : [])].map(h => ({
        name: h.name, number: h.contact, description: `${r === 'IN' ? 'India' : r}, free and confidential`, region: r,
      }))),
      ...(region === 'INTL' ? [{ name: DIRECTORY.name, number: DIRECTORY.contact, description: 'Worldwide directory', region: 'INTL' }] : []),
    ],
    emergency: list.map(r => ({ region: r, number: HELPLINES[r].emergency })),
    immediate_actions: [
      'Reach out to a trusted friend, family member, or counselor',
      `If you are in immediate danger, call ${emergencyNumber(region)} or go to the nearest emergency department`,
    ],
  };
}

/** One sentence naming the right helpline, for fallback and error messages. */
function helplineSentence(region = regionFrom()) {
  return region === 'INTL'
    ? 'Tele-MANAS (14416, India), 988 (US), or your local emergency number'
    : `${HELPLINES[region].primary.name} (${HELPLINES[region].primary.contact}) or ${HELPLINES[region].emergency} in an emergency`;
}

module.exports = { safetyReply, concernFooter, resources, helplineSentence, regionFrom, HELPLINES };
